const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const boston = ee.Geometry.Point([-71.0589, 42.3601]);
  const startDate = '2019-01-29';
  const endDate = '2019-02-06'; // Exclusive end date to include Feb 5

  // 2. Data Acquisition - ERA5-Land for temperature at 2m
  const tempCollection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(boston)
    .select('temperature_2m');

  // Check if collection has data
  const collectionSize = tempCollection.size().getInfo();
  if (collectionSize === 0) {
    print("No temperature data found for the specified period.");
    print("<answer>C1</answer>");
    return;
  }

  print(`ERA5-Land images found: ${collectionSize}`);

  // 3. Calculate daily maximum temperatures
  // Group by day and calculate max temperature for each day
  const dailyMax = tempCollection
    .map(function(image) {
      const date = image.date();
      const day = date.format('YYYY-MM-dd');
      return image.set('date', day);
    })
    .reduceColumns({
      reducer: ee.Reducer.max().group(0, 'date'),
      selectors: ['temperature_2m', 'date']
    });

  const dailyMaxValues = dailyMax.get('groups').getInfo();

  if (!dailyMaxValues || dailyMaxValues.length === 0) {
    print("No daily maximum temperatures calculated.");
    print("<answer>C3</answer>");
    return;
  }

  // Extract temperature values and convert from Kelvin to Celsius
  const tempsCelsius = dailyMaxValues.map(group => {
    const tempK = group.max;
    return tempK - 273.15; // Convert Kelvin to Celsius
  });

  print(`Daily max temperatures (°C): ${tempsCelsius.map(t => t.toFixed(1)).join(', ')}`);
  print(`Days with data: ${tempsCelsius.length}`);

  // Check if we have valid temperature data
  if (tempsCelsius.length === 0) {
    print("No valid temperature data after processing.");
    print("<answer>C2</answer>");
    return;
  }

  // Validate temperature range (sanity check)
  const validTemps = tempsCelsius.filter(temp => temp > -50 && temp < 50);
  if (validTemps.length !== tempsCelsius.length) {
    print("Invalid temperature values detected.");
    print("<answer>C3</answer>");
    return;
  }

  // 4. Calculate temperature range
  const maxTemp = Math.max(...tempsCelsius);
  const minTemp = Math.min(...tempsCelsius);
  const tempRange = maxTemp - minTemp;

  print(`Max daily temp: ${maxTemp.toFixed(1)}°C`);
  print(`Min daily temp: ${minTemp.toFixed(1)}°C`);
  print(`Temperature range: ${tempRange.toFixed(1)}°C`);

  // 5. Final answer
  if (tempRange >= 22) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
